fullRepresentation: FullRepresentation {
    id: xpNotificationHistory
    // Plasma 6.7 derives heading insets from popup padding, which in turn
    // depends on the heading width. XP's flat history header needs no
    // horizontal overhang; break that geometry feedback while XP is active.
    Binding {
        target: xpNotificationHistory.header
        property: "leftInset"
        value: 0
        when: Notifications.Globals.xpBalloons
    }
    Binding {
        target: xpNotificationHistory.header
        property: "rightInset"
        value: 0
        when: Notifications.Globals.xpBalloons
    }

